const canvas=document.getElementById('farm'),ctx=canvas.getContext('2d');
const seasons=[{name:'Spring',icon:'🌷',sky:'#bfe0d5',grass:'#91bd82',dark:'#689b70',flower:'#f9f1dd',weather:'A gentle spring day',sub:'Perfect for tending your garden',weatherIcon:'🌤️'},{name:'Summer',icon:'☀️',sky:'#a8d7e5',grass:'#88b96d',dark:'#5d965d',flower:'#fff0a8',weather:'A golden summer day',sub:'The sun is helping everything grow',weatherIcon:'☀️'},{name:'Autumn',icon:'🍂',sky:'#e8cba9',grass:'#b7a56c',dark:'#8c8a58',flower:'#e69353',weather:'A crisp autumn breeze',sub:'The leaves are turning just for you',weatherIcon:'🍂'},{name:'Winter',icon:'❄️',sky:'#b9d1df',grass:'#d8e4de',dark:'#a9c5be',flower:'#f8fbf6',weather:'A quiet winter morning',sub:'A little frost makes a cozy farm',weatherIcon:'❄️'}];
const crops={radish:{name:'Pink radish',icon:'🫜',season:0,cost:8,sell:20,grow:2,seed:'🌱'},berry:{name:'Sweet berry',icon:'🍓',season:0,cost:12,sell:30,grow:3,seed:'🌿'},tomato:{name:'Sun tomato',icon:'🍅',season:1,cost:10,sell:25,grow:2,seed:'🌱'},melon:{name:'Honey melon',icon:'🍈',season:1,cost:16,sell:40,grow:3,seed:'🌿'},pumpkin:{name:'Little pumpkin',icon:'🎃',season:2,cost:12,sell:32,grow:2,seed:'🌱'},cranberry:{name:'Cranberry',icon:'🫐',season:2,cost:15,sell:38,grow:3,seed:'🌿'},snowpea:{name:'Snow pea',icon:'🫛',season:3,cost:9,sell:24,grow:2,seed:'🌱'},turnip:{name:'Frost turnip',icon:'🥕',season:3,cost:14,sell:36,grow:3,seed:'🌿'}};
const initial={day:1,season:0,gold:48,energy:8,basket:0,tool:'hoe',selected:'radish',seeds:{radish:4,berry:2,tomato:0,melon:0,pumpkin:0,cranberry:0,snowpea:0,turnip:0},plots:Array.from({length:9},()=>({tilled:false,crop:null,stage:0,watered:false})),weather:0};
let game;try{game={...initial,...JSON.parse(localStorage.getItem('littleAcreSave')||'{}')};if(!Array.isArray(game.plots)||game.plots.length!==9)game.plots=initial.plots;game.plots=game.plots.map(p=>({...{tilled:false,crop:null,stage:0,watered:false},...p}));}catch{game=structuredClone(initial)}
let toastTimer;const toastEl=document.getElementById('toast');
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function save(){try{localStorage.setItem('littleAcreSave',JSON.stringify(game))}catch{}}
function currentCrops(){return Object.keys(crops).filter(k=>crops[k].season===game.season)}
function setTool(tool){game.tool=tool;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));const labels={hoe:'Till a patch of earth',seed:`Plant ${crops[game.selected].name.toLowerCase()}`,water:'Give your seedlings a drink',harvest:'Pick ripe crops'};document.getElementById('toolNote').textContent=labels[tool];save();draw()}
function render(){const season=seasons[game.season];document.getElementById('seasonIcon').textContent=season.icon;document.getElementById('seasonName').textContent=season.name;document.getElementById('headerDay').textContent=`Day ${((game.day-1)%7)+1} · ${season.name}`;document.getElementById('headerWeather').textContent=season.weatherIcon;document.getElementById('weatherIcon').textContent=season.weatherIcon;document.getElementById('weatherTitle').childNodes[0].textContent=season.weather;document.getElementById('weatherSub').textContent=season.sub;document.getElementById('dayStat').innerHTML=`Day ${((game.day-1)%7)+1} <span>of ${season.name}</span>`;document.getElementById('goldStat').innerHTML=`${game.gold} <span>g</span>`;document.getElementById('energyStat').innerHTML=`${game.energy} <span>/ 8</span>`;document.getElementById('basketStat').innerHTML=`${game.basket} <span>crops</span>`;document.getElementById('seedList').innerHTML=currentCrops().map(id=>{const c=crops[id],selected=id===game.selected;return `<div class="seed-row ${selected?'selected':''}" data-seed="${id}"><span class="seed-emoji">${c.seed}</span><div class="seed-info"><div class="seed-name">${c.name}</div><div class="seed-detail">${c.grow} days · sells ${c.sell}g</div></div><span class="seed-count">×${game.seeds[id]||0}</span><button class="seed-buy" data-buy="${id}" aria-label="Buy ${c.name} seeds for ${c.cost} gold">+${c.cost}g</button></div>`}).join('');document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===game.tool));save();draw()}
document.getElementById('seedList').addEventListener('click',e=>{const buy=e.target.closest('[data-buy]');if(buy){e.stopPropagation();const id=buy.dataset.buy,c=crops[id];if(game.gold<c.cost){toast('Not quite enough pocket money 🌼');return}game.gold-=c.cost;game.seeds[id]=(game.seeds[id]||0)+1;game.selected=id;toast(`One ${c.name.toLowerCase()} seed added to your bag!`);render();return}const row=e.target.closest('[data-seed]');if(row){game.selected=row.dataset.seed;if(game.tool==='seed')setTool('seed');render()}});
document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
document.getElementById('nextDay').addEventListener('click',nextDay);
document.getElementById('helpBtn').addEventListener('click',()=>showModal('🌱','A little guide to growing','Use <b>Till</b> to prepare soil, choose a seasonal seed, then <b>Plant</b> and <b>Water</b> it. Crops only grow on days you water them. End the day to let time pass; when a crop is ripe, choose <b>Pick</b> and tap its plot to sell it for gold. Buy more seeds whenever you like. A new season arrives every seven days!'));
function showModal(art,title,text){document.getElementById('modalArt').textContent=art;document.getElementById('modalTitle').textContent=title;document.getElementById('modalText').innerHTML=text;document.getElementById('modal').classList.add('open')}
document.getElementById('modalClose').addEventListener('click',()=>document.getElementById('modal').classList.remove('open'));document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')});
function nextDay(){const before=game.season;game.plots.forEach(p=>{if(p.crop&&p.watered&&p.stage<crops[p.crop].grow)p.stage++;p.watered=false});game.day++;game.energy=8;game.weather=Math.random();if(Math.floor((game.day-1)/7)%4!==before){game.season=(game.season+1)%4;let lost=0;game.plots.forEach(p=>{if(p.crop&&crops[p.crop].season!==game.season){p.crop=null;p.stage=0;p.watered=false;lost++}});if(lost)toast(`A new season arrived; ${lost} out-of-season crop${lost===1?'':'s'} faded away.`);else toast(`${seasons[game.season].name} has arrived! New seeds are in 🌱`)}else toast('A new day, a fresh start ☀️');render()}
function plotAction(i){const p=game.plots[i];if(game.tool==='harvest'&&p.crop&&p.stage>=crops[p.crop].grow){const c=crops[p.crop];game.gold+=c.sell;game.basket++;p.crop=null;p.stage=0;p.watered=false;toast(`Lovely ${c.name.toLowerCase()}! +${c.sell}g 🧺`);render();return}if(game.energy<=0){toast('You are all tuckered out. End the day to rest! 😴');return}if(game.tool==='hoe'){if(p.crop){toast('There is already something growing here 🌱');return}if(p.tilled){toast('This patch is ready for a seed!');return}p.tilled=true;game.energy--;toast('A neat little patch, ready to plant! 🌱')}else if(game.tool==='seed'){if(!p.tilled){toast('Till this patch first with your hoe ⛏️');return}if(p.crop){toast('This patch already has a seedling 🌿');return}if(!(game.seeds[game.selected]>0)){toast(`No ${crops[game.selected].name.toLowerCase()} seeds left — tap + to buy one.`);return}if(crops[game.selected].season!==game.season){toast('That seed belongs to another season 🌦️');return}p.crop=game.selected;p.stage=0;p.watered=false;game.seeds[game.selected]--;game.energy--;toast(`${crops[game.selected].name} planted. Give it a drink!`)}else if(game.tool==='water'){if(!p.crop){toast('Nothing planted here to water 💧');return}if(p.watered){toast('This little one is already watered today 💦');return}p.watered=true;game.energy--;toast('A refreshing drink for your plant 💧')}else if(game.tool==='harvest'){if(!p.crop){toast('This patch is waiting for a seed 🌱');return}if(p.stage<crops[p.crop].grow){toast(`${crops[p.crop].name} needs a little more time 🌿`);return}}render()}
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*720/r.width,y=(e.clientY-r.top)*480/r.height;const g=gridBox();if(x>=g.x&&x<g.x+g.w&&y>=g.y&&y<g.y+g.h){const col=Math.floor((x-g.x)/(g.cellW+g.gap)),row=Math.floor((y-g.y)/(g.cellH+g.gap));if(col<3&&row<3)plotAction(row*3+col)}else if(game.tool==='hoe')toast('Tap one of the nine little garden plots 🌱')});
window.addEventListener('keydown',e=>{if(e.target.tagName==='BUTTON'&&e.key==='Enter')return;if(['1','2','3','4'].includes(e.key))setTool(['hoe','seed','water','harvest'][Number(e.key)-1]);if(e.key==='Enter'&&!document.getElementById('modal').classList.contains('open'))nextDay()});

function gridBox(){return{x:205,y:250,w:310,h:188,cellW:98,cellH:57,gap:8}}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.5;ctx.stroke()}}
function draw(){const W=720,H=480,season=seasons[game.season];if(canvas.width!==W*devicePixelRatio||canvas.height!==H*devicePixelRatio){canvas.width=W*devicePixelRatio;canvas.height=H*devicePixelRatio}ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,W,H);
const sky=ctx.createLinearGradient(0,0,0,250);sky.addColorStop(0,season.sky);sky.addColorStop(1,'#e1ead0');ctx.fillStyle=sky;ctx.fillRect(0,0,W,480);
// distant soft hills
ctx.fillStyle=season.dark;ctx.globalAlpha=.27;ctx.beginPath();ctx.moveTo(0,214);ctx.quadraticCurveTo(104,143,218,206);ctx.quadraticCurveTo(327,133,441,202);ctx.quadraticCurveTo(572,140,720,199);ctx.lineTo(720,275);ctx.lineTo(0,275);ctx.fill();ctx.globalAlpha=1;
// sun and drifting clouds
ctx.fillStyle='#fff9d8';ctx.beginPath();ctx.arc(582,62,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fffdf2';ctx.beginPath();ctx.arc(118,77,18,0,Math.PI*2);ctx.arc(139,69,24,0,Math.PI*2);ctx.arc(164,78,17,0,Math.PI*2);ctx.fill();roundRect(104,77,76,15,8,'#fffdf2');
// meadow
ctx.fillStyle=season.grass;ctx.fillRect(0,206,720,274);ctx.fillStyle=season.dark;ctx.globalAlpha=.13;ctx.fillRect(0,206,720,10);ctx.globalAlpha=1;
// meadow bands
ctx.globalAlpha=.12;for(let i=0;i<5;i++){ctx.fillStyle=i%2?'#eff0b3':'#d7e5a8';ctx.beginPath();ctx.ellipse(80+i*158,391+(i%2)*18,112,32,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// winding path
ctx.fillStyle=game.season===3?'#e7e8d8':'#d6c69a';ctx.globalAlpha=.85;ctx.beginPath();ctx.moveTo(464,290);ctx.bezierCurveTo(565,314,566,360,720,366);ctx.lineTo(720,426);ctx.bezierCurveTo(574,411,542,367,446,346);ctx.closePath();ctx.fill();ctx.globalAlpha=1;
// little farmhouse
ctx.fillStyle='#78624e';ctx.fillRect(521,111,118,98);ctx.fillStyle='#f2d9ad';ctx.fillRect(529,135,102,72);ctx.fillStyle='#c77757';ctx.beginPath();ctx.moveTo(510,139);ctx.lineTo(577,88);ctx.lineTo(649,139);ctx.closePath();ctx.fill();ctx.fillStyle='#af6047';ctx.fillRect(545,151,23,24);ctx.fillRect(590,151,23,24);ctx.fillStyle='#91b6a1';ctx.fillRect(549,155,15,16);ctx.fillRect(594,155,15,16);ctx.fillStyle='#775d43';ctx.fillRect(574,170,24,37);ctx.beginPath();ctx.arc(594,189,2,0,Math.PI*2);ctx.fillStyle='#e7c977';ctx.fill();roundRect(517,205,126,9,3,'#b58e5e');
// fence behind garden
ctx.strokeStyle='#e7d4a9';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(177,247);ctx.lineTo(543,247);ctx.moveTo(177,239);ctx.lineTo(543,239);ctx.stroke();for(let x=184;x<=540;x+=36){roundRect(x-4,229,8,27,3,'#e8d9b8')}
// large storybook tree
ctx.fillStyle='#765b3e';ctx.fillRect(82,185,20,76);ctx.fillStyle=season.name==='Autumn'?'#d18a52':season.name==='Winter'?'#718b78':'#628e5c';for(const [x,y,r] of [[77,169,32],[105,150,37],[128,178,31],[90,194,30]]){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}if(game.season!==3){ctx.fillStyle=season.name==='Autumn'?'#e1b06d':'#83aa6d';for(const [x,y] of [[74,149],[111,127],[138,173],[79,190]]){ctx.beginPath();ctx.arc(x,y,5,0,6.28);ctx.fill()}}
// fencing corner posts
ctx.fillStyle='#e6d3ac';for(const x of [180,539]){roundRect(x-5,230,10,26,3,'#eadcbd');roundRect(x-7,229,14,5,2,'#d7bf94')}
// little flowers and grass tufts
for(let i=0;i<30;i++){const x=(i*83+27)%710,y=276+(i*47)%180;if(x>190&&x<526&&y>245&&y<444)continue;ctx.fillStyle=i%4===0?season.flower:'#6d9c63';ctx.beginPath();ctx.arc(x,y,i%4===0?2.5:1.6,0,6.28);ctx.fill()}
// plot bed and nine clickable plots
const g=gridBox();roundRect(g.x-13,g.y-13,g.w+26,g.h+26,15,'#85714f');roundRect(g.x-8,g.y-8,g.w+16,g.h+16,12,game.season===3?'#b0a98e':'#c5ad7e');
for(let i=0;i<9;i++){const col=i%3,row=Math.floor(i/3),x=g.x+col*(g.cellW+g.gap),y=g.y+row*(g.cellH+g.gap),p=game.plots[i];roundRect(x,y+3,g.cellW,g.cellH,9,'#667d4e');const soil=p.tilled?(p.watered?'#70533d':'#956b46'):(game.season===3?'#c0d0c7':'#86ad67');roundRect(x,y,g.cellW,g.cellH,9,soil,p.crop&&p.stage>=crops[p.crop].grow?'#f0c967':null);
if(!p.tilled){ctx.strokeStyle=game.season===3?'#eef4ed':'#638e58';ctx.lineWidth=2;for(let k=0;k<4;k++){const gx=x+15+k*20,gy=y+20+(k%2)*13;ctx.beginPath();ctx.moveTo(gx,gy+4);ctx.lineTo(gx+2,gy);ctx.lineTo(gx+4,gy+4);ctx.stroke()}}else{ctx.strokeStyle=p.watered?'#997b68':'#b98960';ctx.globalAlpha=.45;ctx.lineWidth=1;for(let k=0;k<3;k++){ctx.beginPath();ctx.moveTo(x+10,y+13+k*14);ctx.quadraticCurveTo(x+49,y+9+k*14,x+88,y+13+k*14);ctx.stroke()}ctx.globalAlpha=1}
if(p.crop){const c=crops[p.crop],ripe=p.stage>=c.grow;ctx.textAlign='center';ctx.textBaseline='middle';if(p.stage===0){ctx.font='20px serif';ctx.fillText('•',x+49,y+30)}else if(p.stage===1){ctx.fillStyle='#437b45';ctx.strokeStyle='#437b45';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x+49,y+37);ctx.quadraticCurveTo(x+47,y+24,x+49,y+18);ctx.stroke();ctx.beginPath();ctx.ellipse(x+43,y+23,9,4,-.45,0,6.28);ctx.ellipse(x+55,y+20,8,4,.45,0,6.28);ctx.fill()}else{ctx.font=ripe?'30px serif':'25px serif';ctx.fillText(ripe?c.icon:'🌿',x+49,y+29)}if(p.watered){ctx.fillStyle='#a5d9ea';ctx.beginPath();ctx.ellipse(x+82,y+11,4,6,.25,0,6.28);ctx.fill();}if(ripe){ctx.strokeStyle='#ffed9a';ctx.lineWidth=2;ctx.globalAlpha=.8;ctx.beginPath();ctx.arc(x+49,y+29,20,0,6.28);ctx.stroke();ctx.globalAlpha=1}}
// tiny plot index
ctx.fillStyle='#fff8e2';ctx.globalAlpha=.7;ctx.font='8px sans-serif';ctx.textAlign='left';ctx.fillText(String(i+1),x+6,y+11);ctx.globalAlpha=1}
// Farmer with little watering can, happily looking over the beds
const bob=Math.sin(Date.now()/440)*1.5,px=572,py=302+bob;ctx.fillStyle='#344b3b';ctx.beginPath();ctx.ellipse(px,py+27,15,5,0,0,6.28);ctx.fill();roundRect(px-9,py+5,18,22,6,'#628b64');ctx.fillStyle='#edc69c';ctx.beginPath();ctx.arc(px,py,9,0,6.28);ctx.fill();roundRect(px-10,py-5,20,7,3,'#c27b56');ctx.fillStyle='#583e36';ctx.beginPath();ctx.arc(px-3,py,1,0,6.28);ctx.arc(px+3,py,1,0,6.28);ctx.fill();ctx.strokeStyle='#f0d7b4';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(px-5,py+26);ctx.lineTo(px-8,py+34);ctx.moveTo(px+5,py+26);ctx.lineTo(px+8,py+34);ctx.stroke();
// seasonal atmosphere
if(game.season===3){ctx.fillStyle='#fff';ctx.globalAlpha=.3;for(let i=0;i<30;i++){const x=(i*127+Math.floor(Date.now()/100))%720,y=(i*73+Math.floor(Date.now()/160))%480;ctx.beginPath();ctx.arc(x,y,1.3,0,6.28);ctx.fill()}ctx.globalAlpha=1}
}
render();setTool(game.tool);document.getElementById('hint').style.opacity='1';setTimeout(()=>document.getElementById('hint').style.opacity='0',7000);

